import SwiftUI
struct HomeView:View{@StateObject private var viewModel=HomeViewModel();var body:some View{Group{if let user=viewModel.sessionUser{ShopHomeView(user:user,viewModel:viewModel)}else{LoginView(viewModel:viewModel)}}}}
private struct LoginView:View{@ObservedObject var viewModel:HomeViewModel;var body:some View{NavigationStack{VStack(spacing:16){Text("HIND PHARMA").font(.largeTitle.bold());Text("Login to start your shop work").foregroundStyle(.secondary);TextField("Username",text:$viewModel.username).textInputAutocapitalization(.never).autocorrectionDisabled().textFieldStyle(.roundedBorder);SecureField("Password",text:$viewModel.password).textFieldStyle(.roundedBorder);if let error=viewModel.errorMessage{Text(error).foregroundStyle(.red).font(.footnote)};Button{Task{await viewModel.login()}}label:{if viewModel.isLoading{ProgressView()}else{Text("LOGIN")}}.frame(maxWidth:.infinity).buttonStyle(.borderedProminent).disabled(viewModel.isLoading)}.padding().navigationTitle("Login")}}}
private struct ShopHomeView:View{let user:SessionUser;@ObservedObject var viewModel:HomeViewModel;private let actions:[(String,Set<String>)]=[("Daily Calling",["admin","manager","employee"]),("Medical List",["admin","manager","employee"]),("Products",["admin","manager","employee"]),("Order",["admin","manager","employee"]),("Manager Dashboard",["admin","manager"]),("Admin Dashboard",["admin"]),("HTG Super Admin",["super_admin"])];var body:some View{NavigationStack{List{Section{Text(user.businessName ?? "Hind Pharma").font(.title2.bold());Text("\(user.username) · \(user.roleDisplayName)").foregroundStyle(.secondary)}Section("Home"){ForEach(actions.filter{$0.1.contains(user.role)},id:\.0){a in if a.0=="Daily Calling"{NavigationLink(a.0){DailyCallingView(user:user)}}else if a.0=="Medical List"||a.0=="Products"||a.0=="Order"{NavigationLink(a.0){NativeOrderFlowView(user:user)}}else if a.0=="Manager Dashboard"{NavigationLink(a.0){ManagerDashboardView(user:user)}}else if a.0=="Admin Dashboard"{NavigationLink(a.0){AdminDashboardView(user:user)}}else{NavigationLink(a.0){SuperAdminDashboardView(user:user)}}}}Section{Button("Logout",role:.destructive,action:viewModel.logout)}}.navigationTitle("Hind Pharma")}}}
private struct NativeOrderFlowView:View{let user:SessionUser;@State private var medical:SelectedMedical?;@State private var cart:[CartItem]=[];@State private var stage=0;var body:some View{Group{if stage==0||medical==nil{MedicalListView(user:user){m in medical=m;stage=1}}else if stage==1{ProductListView(user:user,medical:medical!,onOrder:{items in cart=items;stage=2})}else{OrderView(user:user,medical:medical!,initialItems:cart,onBack:{stage=1},onNewOrder:{cart=[];medical=nil;stage=0})}}}}
#Preview{HomeView()}